// 官网验证码介绍页体验
var js = document.createElement('script');
js.src = 'https://turing.captcha.qcloud.com/TCaptcha.js';
document.head.appendChild(js);
var captchaTimer = null;
window.captchaCallback = function () {
  console.log('验证成功');
};
window.captchaCallbackNoFeel = function () {
  Toast('验证成功', 2000);
};
function Toast(msg, duration) {
  duration = isNaN(duration) ? 3000 : duration;
  var m = document.createElement('div');
  m.innerHTML = msg;
  m.style.cssText =
    'max-width:60%;min-width: 150px;padding:0 14px;height: 40px;color: rgb(255, 255, 255);line-height: 40px;text-align: center;border-radius: 4px;position: fixed;top: 50%;left: 50%;transform: translate(-50%, -50%);z-index: 999999;background: rgba(0, 0, 0,.7);font-size: 16px;';
  document.body.appendChild(m);
  setTimeout(function () {
    var d = 0.5;
    m.style.webkitTransition = '-webkit-transform ' + d + 's ease-in, opacity ' + d + 's ease-in';
    m.style.opacity = '0';
    setTimeout(function () {
      document.body.removeChild(m);
    }, d * 1000);
  }, duration);
}
function init() {
  console.log(window.TencentCaptcha);
  if (window.TencentCaptcha) {
    clearTimeout(captchaTimer);
    captchaTimer = null;
    document.getElementById('captcha_click').onclick = function () {
      new TencentCaptcha('199999861', captchaCallback, {}).show();
    };
    document.getElementById('vtt_click').onclick = function () {
      new TencentCaptcha('199999726', captchaCallback, {}).show();
    };
    document.getElementById('text_click').onclick = function () {
      new TencentCaptcha('199999888', captchaCallback, {}).show();
    };
    document.getElementById('noFeel_click').onclick = function () {
      new TencentCaptcha('199999399', captchaCallbackNoFeel, { loading: false }).show();
    };
    document.getElementById('image_click').onclick = function () {
      new TencentCaptcha('199999761', captchaCallback, {}).show();
    };
  } else {
    captchaTimer = setTimeout(function () {
      init();
    }, 500);
  }
}
init();
